import{z as n,x as A,o as r,c as d,q as i,j as o,D as E,d as s,s as l,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"指标、日志与追踪","description":"","frontmatter":{"title":"指标、日志与追踪","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/obs-metrics-logs-traces.md","filePath":"cs/obs-metrics-logs-traces.md","lastUpdated":1791063341000}'),p={name:"cs/obs-metrics-logs-traces.md"};function m(c,a,h,f,D,u){const t=A("Mermaid");return r(),d("div",null,[a[2]||(a[2]=i('<h1 id="指标、日志与追踪" tabindex="-1">指标、日志与追踪 <a class="header-anchor" href="#指标、日志与追踪" aria-label="Permalink to &quot;指标、日志与追踪&quot;">​</a></h1><div class="epigraph"><p>每一种遥测信号都在为一种提问方式付存储与延迟的账；先定你要问什么，再选柱子，而不是先把三根柱子都立满再找问题。</p><footer>—— 据 Gregg, <em>Systems Performance</em>, 2nd ed., 2018；Google SRE 书中的监控章节整理</footer></div><p><a href="/cs/virt-case-map">上一课</a>给「虚拟化与容器深入」收束：租户互信、密度目标、负载路径三问定机制，五个案例钉在一根「共享内核到复制机器」的轴上——隔离与开销同向移动，没有免费的边界。边界之外的系统跑起来之后，先得能被看见。显式的系统更要显式的观测——编排出的一百个进程谁慢、谁错了，内核不会自己报上来。本课程「可观测性与调试」深钻由此起笔。三支柱的分工与关联，主干课<a href="/cs/observability-pillars">可观测三支柱</a>已钉过：指标聚合、日志细节、追踪请求图，用 id 关联，控制基数。本课不重讲口号，写把柱子立进生产时的三笔工程账：基数、成本与采样。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>支柱分工是名词，工程账是动词。第一笔是基数：指标的一个标签组合就是一条时间序列，序列数是各标签基数的叉积 \\(|L_1|\\times\\cdots\\times|L_k|\\)。把 user id 放进指标标签，序列数立刻是用户数乘端点数乘实例数——写入还撑得住，索引与慢查询先把时序库拖垮。第二笔是日志的形态：非结构化文本 grep 得了一台机器，聚不得一片集群；无字段的日志没法回答「哪些用户受了影响」。第三笔是追踪全量不可行：全采的存储与网络开销按请求量线性走，而丢掉的采样里恰恰藏着最稀有的错误。三笔账共同回答一个问题：在预算之内，让哪类问题变得可答。</p><p><span class="marginnote">常见误区：初学者以为日志打得越多越安全。无结构的文本日志在一台机器上还能 grep，到了一片集群上没法按字段聚合，「哪些用户受了影响」这种问题一条也答不出来，存储倒是照付。</span></p><h3 id="三种信号-三种聚合粒度" tabindex="-1">三种信号，三种聚合粒度 <a class="header-anchor" href="#三种信号-三种聚合粒度" aria-label="Permalink to &quot;三种信号，三种聚合粒度&quot;">​</a></h3><p>指标是预聚合：常开、便宜，但只有你预先定义过的维度。日志是事件级：每个细节都在，但检索与存储都贵。追踪是请求级：span 把一次调用串成因果树，回答「这一次发生了什么」。信号从应用与系统事件流里分岔：可聚合、低基数的进指标；带细节、带 trace id 的进结构化日志；跨进程边界的上下文进 span。</p><p><span class="marginnote">单实例时序库的活跃序列到数百万量级就是现实上限，靠标签纪律省钱，不是靠加机器。一张失控的直方图标签能在一夜里烧掉整月预算。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>类型纪律先行：gauge 记瞬时值，counter 只单调递增并在消费端求速率，histogram 存分布并在消费端取分位数。错误率永远写成 \\(\\Delta\\mathrm{errors}/\\Delta\\mathrm{total}\\) 的 counter 比值，不写平均值嵌平均值。日志结构化：一行一个事件，字段名跨服务稳定，级别有语义约定——ERROR 是会吵醒人的，WARN 是该看的，DEBUG 是不该在生产开的。trace id 写进每条与请求相关的日志。追踪采样默认 head-based 低比率加错误强制采样，具体策略留给追踪工程课。基数预算用登记制执行：新标签先过预算评审，高基数字段只进日志与追踪，不进无限扩张的指标标签。</p><p><span class="marginnote">术语翻译：gauge 是体温计（记当前值，可升可降）；counter 是里程表（只涨不跌，想知道速率就在消费端做差）；histogram 是把一万个测量值分进几十个桶数个数，分位数从桶里估。</span></p>',12)),(r(),o(B,null,{default:E(()=>[l(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20EV%5B%22%E5%BA%94%E7%94%A8%E4%B8%8E%E7%B3%BB%E7%BB%9F%E4%BA%8B%E4%BB%B6%E6%B5%81%22%5D%20--%3E%20MET%5B%22%E6%8C%87%E6%A0%87%EF%BC%9A%E8%81%9A%E5%90%88%EF%BC%8C%E5%9F%BA%E6%95%B0%E5%8F%97%E9%A2%84%E7%AE%97%22%5D%0A%20%20EV%20--%3E%20LOG%5B%22%E7%BB%93%E6%9E%84%E5%8C%96%E6%97%A5%E5%BF%97%EF%BC%9A%E4%B8%80%E8%A1%8C%E4%B8%80%E4%BA%8B%E4%BB%B6%EF%BC%8C%E5%B8%A6%20trace%20id%22%5D%0A%20%20EV%20--%3E%20TR%5B%22span%EF%BC%9A%E8%B7%A8%E8%BF%9B%E7%A8%8B%E4%B8%8A%E4%B8%8B%E6%96%87%22%5D%0A%20%20MET%20--%3E%20AL%5B%22%E6%8C%87%E6%A0%87%E5%91%8A%E8%AD%A6%22%5D%0A%20%20AL%20--%3E%20PICK%5B%22%E6%8C%91%E4%B8%80%E6%9D%A1%E5%9D%8F%20trace%22%5D%0A%20%20PICK%20--%3E%20SEE%5B%22%E6%8C%89%E6%97%B6%E9%97%B4%E6%88%B3%E7%BF%BB%E6%97%A5%E5%BF%97%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"基数为什么会爆炸：叉积里每加一个十值标签，序列数乘十；内存与索引随序列数线性涨，慢查询互相挤占，最后观测系统自己成为故障源——观测平面失效时你恰好最需要它。日志为什么必须结构化：字段即索引，稳定字段名才让「按用户、按错误码聚合」从翻文本变成一次查询。采样为什么按树决策：head-based 在根上决定整棵树采不采，采半棵树拼不出因果边，比不采更误导。直方图桶是分辨率与成本的折中：桶太疏，分位数失真，SLO 的分母还没算就错了。最后，观测本身有开销——序列化、出核、采样都在消耗被测系统的资源，这个 probe effect 到 perf 一课会再算。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"数字实例：基数是乘法不是加法——3 个状态值 × 10 个端点 = 30 条序列，还好；再塞一个一万用户的 user id 标签，立刻是 30 万条，外加实例数再乘一遍。加标签前先在心里把这乘法做完。")],-1)),(r(),o(B,null,{default:E(()=>[l(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20B%5B%22%E5%9F%BA%E7%A1%80%E5%BA%8F%E5%88%97%20%E7%8A%B6%E6%80%81%203%20%E5%80%BC%22%5D%20--%3E%20B1%5B%223%20%E6%9D%A1%E5%BA%8F%E5%88%97%22%5D%0A%20%20B1%20--%3E%20C%5B%22%E5%8A%A0%E6%A0%87%E7%AD%BE%20%E7%AB%AF%E7%82%B9%2010%20%E5%80%BC%22%5D%0A%20%20C%20--%3E%20C1%5B%223%20%C3%97%2010%20%3D%2030%20%E6%9D%A1%22%5D%0A%20%20C1%20--%3E%20D%5B%22%E5%86%8D%E5%8A%A0%E6%A0%87%E7%AD%BE%20user_id%20%E4%B8%80%E4%B8%87%E5%80%BC%22%5D%0A%20%20D%20--%3E%20D1%5B%2230%20%E4%B8%87%E6%9D%A1%20%E5%BA%8F%E5%88%97%E7%88%86%E7%82%B8%22%5D%0A%20%20D1%20--%3E%20E%5B%22%E7%B4%A2%E5%BC%95%E4%B8%8E%E6%85%A2%E6%9F%A5%E8%AF%A2%E6%8B%96%E5%9E%AE%E6%97%B6%E5%BA%8F%E5%BA%93%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写具体后端的查询语言与部署形态，不写安全日志的合规保留——那是<a href="/cs/siem-logging">SIEM</a>的口径。剖析（profile）常被称作第四根柱子，本课只点名：工具组后四课——<a href="/cs/ebpf-observability">eBPF</a> 的动态埋点、perf 的测量学、火焰图的展示、内存的正确性调试——都长在它上面。单机单请求的答案不等于系统答案：服务整体好不好，是工程组 SLO 一课的问题。下一课写不动应用代码就能把埋点挂进事件流的 eBPF。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>指标聚合、日志细节、追踪请求图；选信号就是选提问方式。</li><li>指标吃基数预算：登记制、高基数字段不进指标标签。</li><li>日志结构化、字段名稳定、trace id 关联三柱。</li><li>采样按树决策，错误路径强制保留。</li><li>观测有 probe effect，观测平面自身要被监控。</li><li>出处：Gregg, <em>Systems Performance</em>, 2nd ed., 2018；Google SRE 书监控章节；OpenTelemetry 对 signals 的划分口径。</li></ul>',4))])}const C=n(p,[["render",m]]);export{b as __pageData,C as default};
